import React from "react";
import { motion } from "framer-motion";
import { FEATURES } from "./Content";
import { Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck } from "lucide-react";

const icons = [Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck];

export default function WhyChooseUs() {
  return (
    <section id="why" className="section" style={{ background: "#fff" }}>
      <div className="container mx-auto">
        {/* Header */}
        <motion.div
          className="mb-10"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <div className="flex items-center gap-3 mb-4">
            <div className="w-8 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="overline">Why Choose Us</span>
          </div>
          <h2 className="section-title">
            Built for <strong>professionals</strong> who care about <span>finish</span>.
          </h2>
          <p className="section-subtitle mt-4">
            Six promises that have kept India's most demanding decorators coming back. From custom sizing to nationwide logistics — we keep your event on schedule and on style.
          </p>
        </motion.div>

        {/* Features Grid */}
        <div className="features-grid">
          {FEATURES.map((f, i) => {
            const Icon = icons[i % icons.length];
            return (
              <motion.div
                key={f.title}
                className="card"
                initial={{ opacity: 0, y: 30 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.08, duration: 0.5 }}
                whileHover={{ y: -4 }}
              >
                <div
                  className="w-12 h-12 rounded-xl flex items-center justify-center mb-4"
                  style={{ background: "rgba(212,175,55,0.12)" }}
                >
                  <Icon size={24} strokeWidth={1.5} color="#d4af37" />
                </div>
                <h3 className="font-semibold text-lg mb-2" style={{ color: "#1a080a" }}>
                  {f.title}
                </h3>
                <p className="text-sm" style={{ color: "rgba(26,8,10,0.7)", lineHeight: 1.6 }}>
                  {f.desc}
                </p>
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
